import { getElement } from '../../utils/functional';

class UpdateContinueButton {
  constructor() {
    this.setupEls = this.setupEls.bind(this);
    this.init = this.init.bind(this);
    this.setupEls();
    this.init();
  }

  setupEls() {
    this.els = {
      arrowHtmlEl: getElement('.js-ArrowHtml'),
      continueButtonEl: getElement('#continue_button')
    };
  }

  init() {
    if (this.arrowHtml && this.els.continueButtonEl) {
      this.els.continueButtonEl.innerHTML += this.arrowHtml;
    }
  }

  get arrowHtml() {
    if (!this.els.arrowHtmlEl || !this.els.arrowHtmlEl.innerHTML.length) return null;
    return this.els.arrowHtmlEl.innerHTML;
  }

}

function updateContinueButton() {
  return new UpdateContinueButton();
}

updateContinueButton();